from pathlib import Path
import subprocess
ROOT=Path(__file__).resolve().parents[2]
ap=argparse.ArgumentParser();ap.add_argument('--helper',type=Path,default=ROOT/'work/build/thumbnail-helper/thumbnail-helper');ap.add_argument('--output',type=Path,required=True);a=ap.parse_args()
a.helper=a.helper.resolve();a.output=a.output.resolve()
