 root=Path(folder);first=root/'first.bin';second=root/'second.bin';link=root/'source.bin'
 first.write_bytes(b'a'*(8*1024*1024));second.write_bytes(b'b'*(8*1024*1024));link.symlink_to(first)
 before=identity(first,'stat');sampled=identity(first,'sampled');unchanged=identity(first,'sampled')
